// src/screens/SignupScreen.jsx
// SAME UI as original. Supabase signUp → Django REST /api/auth/register/

import { useState } from "react";
import { registerUser } from "../services/authService";
import { signupBg, mainLogo } from "../assets/images";

export default function SignupScreen({ onNavigate }) {
  const [form, setForm] = useState({
    name: "", contactNumber: "", province: "", municipality: "", barangay: "", password: "",
  });
  const [loading, setLoading] = useState(false);
  const [error, setError]     = useState("");

  const set = (key) => (e) => setForm((f) => ({ ...f, [key]: e.target.value }));

  const handleSignUp = async (e) => {
    e.preventDefault();
    setError("");

    const { name, contactNumber, province, municipality, barangay, password } = form;

    // Validation
    if (!name || !contactNumber || !province || !municipality || !barangay || !password) {
      setError("Please fill in all fields."); 
      return;
    }
    if (password.length < 6) { 
      setError("Password must be at least 6 characters."); 
      return; 
    }
    if (contactNumber.length < 10) { 
      setError("Please enter a valid contact number (at least 10 digits)."); 
      return; 
    }

    setLoading(true);

    // Prepare the data exactly as your backend expects
    const registrationData = {
      username: contactNumber.trim(), // Use contactNumber as username
      password: password.trim(),
      full_name: name.trim(),
      province: province.trim(),
      municipality: municipality.trim(),
      barangay: barangay.trim(),
    };

    console.log("Sending registration data:", registrationData);

    const { data, error: regError } = await registerUser(
      registrationData.username,
      registrationData.password,
      {
        full_name: registrationData.full_name,
        province: registrationData.province,
        municipality: registrationData.municipality,
        barangay: registrationData.barangay,
      }
    );

    if (regError) {
      console.error("Registration error details:", regError);

      // Try to parse the error if it's a string
      let errorMessage = regError;
      try {
        const parsedError = JSON.parse(regError);
        if (parsedError.username) {
          errorMessage = `Username: ${parsedError.username.join(', ')}`;
        } else if (parsedError.password) {
          errorMessage = `Password: ${parsedError.password.join(', ')}`;
        } else if (parsedError.full_name) {
          errorMessage = `Full Name: ${parsedError.full_name.join(', ')}`;
        } else if (typeof parsedError === 'object') {
          errorMessage = Object.values(parsedError).flat().join(', ');
        }
      } catch(e) {
        // If it's not JSON, use as is
      }

      setError(errorMessage);
      setLoading(false);
      return;
    }

    console.log("Registration successful:", data);

    // On success: go to login with phone prefilled
    onNavigate("login", { phone: contactNumber.trim() });
    setLoading(false);
  };

  return (
    <div
      className="auth-root"
      style={{ backgroundImage: `url(${signupBg})`, backgroundSize: "cover", backgroundPosition: "center top" }}
    >
      <div className="auth-card" style={{ maxWidth: 480, maxHeight: "90vh", overflowY: "auto" }}>
        <div className="auth-logo">
          <img 
            src={mainLogo} 
            alt="Scarecrow Logo" 
            style={{ width: 52, height: 52, objectFit: "contain", borderRadius: 12 }} 
          />
          <div className="auth-logo-text">Scare<span>Crow</span></div>
        </div>

        <h1 className="auth-title">SIGN UP</h1>
        <p className="auth-subtitle">Please fill in the details</p>

        <form onSubmit={handleSignUp}>
          <div className="form-group">
            <label className="form-label">Full Name</label>
            <input 
              className="form-input" 
              placeholder="FULL NAME" 
              value={form.name} 
              onChange={set("name")} 
              disabled={loading} 
              required
            />
          </div>

          <div className="form-group">
            <label className="form-label">Contact Number (Username)</label>
            <input 
              className="form-input" 
              type="tel" 
              placeholder="CONTACT NUMBER (e.g., 09123456789)" 
              value={form.contactNumber} 
              onChange={set("contactNumber")} 
              disabled={loading} 
              required
            />
            {form.contactNumber.length > 0 && (
              <p className="form-hint">You'll use {form.contactNumber} to log in</p>
            )}
          </div>

          <div className="form-section-label">Address</div>

          <div className="form-grid">
            <div className="form-group">
              <label className="form-label">Province</label>
              <input 
                className="form-input" 
                placeholder="PROVINCE" 
                value={form.province} 
                onChange={set("province")} 
                disabled={loading} 
                required
              />
            </div>
            <div className="form-group">
              <label className="form-label">Municipality / City</label>
              <input 
                className="form-input" 
                placeholder="MUNICIPALITY / CITY" 
                value={form.municipality} 
                onChange={set("municipality")} 
                disabled={loading} 
                required
              />
            </div>
          </div>

          <div className="form-group">
            <label className="form-label">Barangay</label>
            <input 
              className="form-input" 
              placeholder="BARANGAY" 
              value={form.barangay} 
              onChange={set("barangay")} 
              disabled={loading} 
              required
            />
          </div>

          <div className="form-group">
            <label className="form-label">Create Password</label>
            <input 
              className="form-input" 
              type="password" 
              placeholder="CREATE PASSWORD (min. 6 characters)" 
              value={form.password} 
              onChange={set("password")} 
              autoComplete="new-password" 
              disabled={loading} 
              required
            />
            <p className="form-hint">Password must be at least 6 characters</p>
          </div>

          {error && (
            <div className="error-box" style={{ marginTop: 16 }}>
              ⚠ {error}
            </div>
          )}

          <button className="btn-primary" type="submit" disabled={loading}>
            {loading ? "Creating account…" : "SIGN UP"}
          </button>
        </form>

        <div className="auth-footer-link">
          Already have an account?{" "}
          <button type="button" onClick={() => onNavigate("login")} disabled={loading}>
            Log In
          </button>
        </div>
      </div>
    </div>
  );
}
